mapper.insert:
insert into room (
	room_no, room_owner, room_name, room_limit
)
values(
	#{roomNo}, #{roomOwner}, #{roomName}, #{roomLimit}
)

mapper.delete:
delete 	room_user 
where 	room_no=#{roomNo}
		and 
		account_id = #{accountId}

mapper.select:
select 	account_id from room_user
where 	room_no = #{roomNo}
order by account_id asc
